import { INTERNATIONAL_TOOL_COPY, type GlobalLang, type InternationalLang } from "./internationalTranslations";
import { MSMED_INTEREST_PCT } from "./rbiRates";

export type RegionalToolLanguage = "hi" | "ta" | "te" | "mr";
export type SupportedToolLanguage = RegionalToolLanguage | InternationalLang | GlobalLang;

export type LocalizedToolCopy = {
  name: string;
  title: string;
  description: string;
  intro: string;
  steps: string[];
  faqs: { question: string; answer: string }[];
};

export type LocalizedTool = {
  slug: string;
  name: string;
  component:
    | "digitalCard" | "dynamicQr" | "stickers" | "gst" | "whatsapp"
    | "bulk" | "invoice" | "receipt" | "paidStamp" | "rentReceipt"
    | "paymentReminder" | "quotation" | "splitBill" | "cashDenomination"
    | "creditNote" | "emiCalculator" | "homeLoan" | "educationLoan" | "educationCost" | "fdCalculator" | "rdCalculator" | "gratuity" | "sipCalculator" | "salarySlip" | "msmed" | "proforma" | "breakEven" | "treds"
    | "upiCalculator" | "upiMdr" | "offerPoster"
    | "menuQr" | "margin" | "limits" | "decoder" | "upiLink" | "upiId" | "gstin" | "amountWords" | "upiScanner" | "survey"
    | "merchantRecon" | "msmeReceivables"
    | "influencerContract" | "freelanceContract"
    | "purchaseOrder" | "deliveryChallan" | "debitNote" | "billOfSupply" | "cashMemo"
    | "default";
  copy: Record<SupportedToolLanguage, LocalizedToolCopy>;
};

