        { question: "बँक खाते क्रमांकावरून QR बनवता येतो का?", answer: "नाही. NPCI च्या मसुद्यातील UPI लिंकमध्ये UPI पत्ता आणि नाव यांचेच फील्ड आहेत; खाते क्रमांक किंवा IFSC साठी फील्ड नाही. आधी बँकेच्या UPI अॅपमध्ये तुमच्या खात्यासाठी UPI सुरू करा आणि तिथे मिळालेला UPI ID इथे लिहा." },
        { question: "नाव लिहिणे आवश्यक आहे का?", answer: "होय, हे टूल नाव विचारते. NPCI च्या मसुद्यात UPI पत्त्यासोबत प्राप्तकर्त्याचे नाव हे आवश्यक फील्ड आहे. प्रिंट करण्यापूर्वी पेमेंट स्क्रीनवर दिसणारे नाव आणि UPI ID तपासा." },
        { question: "माझा UPI ID अपलोड किंवा सेव्ह होतो का?", answer: "QR तुमच्या ब्राउझरमध्येच तयार होतो; UPI ID, नाव, रक्कम किंवा नोट आमच्या सर्व्हरवर पाठवली जात नाही. फॉर्मचा ड्राफ्ट फक्त याच ब्राउझरमध्ये सेव्ह राहतो; ब्राउझर डेटा पुसल्यावर तो जातो." }
