      description: "கடை, மேசை, இன்வாய்ஸ் அல்லது WhatsApp-க்கு UPI ID மூலம் இலவச பேமெண்ட் QR உருவாக்குங்கள். இந்தப் பக்கம் இந்தியாவில் UPI கட்டணங்களுக்கானது.",
      intro: "உங்கள் UPI ID-யிலிருந்து பேமெண்ட் QR உருவாக்கி, அதை எங்கே வைப்பது என்று முடிவு செய்யுங்கள்: கவுண்டர், மேசை, இன்வாய்ஸ் அல்லது WhatsApp உரையாடல். இந்தப் பக்கம் இந்தியாவில் UPI கட்டணங்களுக்கு மட்டுமே; இது NPCI, வங்கி அல்லது UPI ஆப் எதனுடனும் தொடர்பில்லாத சுதந்திரமான கருவி.",
