        "“போஸ்டர் வடிவமைப்பு” தாவலில் கடை ஸ்டாண்டி, உணவக மேசை அல்லது ஃப்ரீலான்சர் கார்டு போன்ற வடிவத்தைத் தேர்ந்தெடுக்கவும்; தேவையெனில் தொகை அல்லது இன்வாய்ஸ் எண்ணைச் சேர்க்கவும்",
